def gen(rng):
    close = {'(': ')', '[': ']', '{': '}'}

    def valid(pairs):
        s = []
        stack = []
        opened = 0
        while opened < pairs or stack:
            if opened < pairs and (not stack or rng.random() < 0.5):
                c = rng.choice('([{')
                s.append(c)
                stack.append(c)
                opened += 1
            else:
                s.append(close[stack.pop()])
        return ''.join(s)

    def mutate(s):
        k = rng.randint(0, 3)
        s = list(s)
        if k == 0 and s:
            s[rng.randrange(len(s))] = rng.choice('()[]{}')
        elif k == 1 and s:
            s.pop(rng.randrange(len(s)))
        elif k == 2:
            s.insert(rng.randint(0, len(s)), rng.choice('()[]{}'))
        elif len(s) > 1:
            i = rng.randrange(len(s) - 1)
            s[i], s[i + 1] = s[i + 1], s[i]
        return ''.join(s) if s else '('

    def fmt(s, a):
        return s + '\n' + str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [fmt('()', [1, 2]), fmt('(', [0, 0]), fmt(')(', [3, -4]), fmt('([)]', [1, 2, 3, 4]), fmt('{[]}', [5, 0, 7]),
             fmt('((', [0, 0, 0]), fmt('()[]{}', [-1, -1, -1, -1])]
    for _ in range(14):
        s = valid(rng.randint(1, 8))
        if rng.random() < 0.5:
            s = mutate(s)
        n = rng.randint(2, 8)
        a = [rng.randint(-6, 6) for _ in range(n)]
        tests.append(fmt(s, a))
    n = 100000
    big = [rng.randint(-10**9, 10**9) for _ in range(n)]
    tests.append(fmt(valid(50000), big))
    tests.append(fmt('(' * 50000 + ')' * 50000, [rng.randint(1, 10**9) for _ in range(n)]))
    bad = valid(49999) + ')('
    tests.append(fmt(bad, [0 if i in (7, 90000) else rng.randint(-10**9, 10**9) for i in range(n)]))
    tests.append(fmt('(' * n, [0 if i == 5 else rng.randint(-10**9, 10**9) for i in range(n)]))
    return tests

